$(document).ready(function(){
    // Show preloader initially and add body class
    $('#preloader').show();
    $('body').addClass('preloader-active');
    
    // Preloader functionality
    $(window).on('load', function() {
        $('#preloader').fadeOut('slow', function() {
            $(this).remove();
            $('body').removeClass('preloader-active');
        });
    });
    
    // Fallback preloader removal after 3 seconds
    setTimeout(function() {
        $('#preloader').fadeOut('slow', function() {
            $(this).remove();
            $('body').removeClass('preloader-active');
        });
    }, 3000);
    
    // Mobile menu functionality
    $('.open_mobile_menu').on('click', function() {
        $('.mobile_menu_wrap').toggleClass('mobile_menu_on');
        $('body').toggleClass('mobile_menu_overlay_on');
    });
    
    // Scroll to top functionality
    $(window).on('scroll', function() {
        if ($(this).scrollTop() > 200) {
            $('.scrollup').fadeIn();
        } else {
            $('.scrollup').fadeOut();
        }
    });
    
    $('.scrollup').on('click', function() {
        $('html, body').animate({
            scrollTop: 0
        }, 800);
        return false;
    });
    
    // Swiper initialization
    if(typeof Swiper !== 'undefined') {
        var slider = new Swiper('.bi-main-slider-4', {
            spaceBetween: 30,
            slidesPerView: 1,
            effect: 'fade',
            loop: true,
            navigation: {
                nextEl: ".bi-main-button-next-4",
                prevEl: ".bi-main-button-prev-4",
            },
        });
    }
    
    // WOW.js initialization
    if(typeof WOW !== 'undefined') {
        new WOW().init();
    }
    
    // Magnific Popup initialization
    if($.fn.magnificPopup) {
        $('.video_box').magnificPopup({
            disableOn: 200,
            type: 'iframe',
            mainClass: 'mfp-fade',
            removalDelay: 160,
            preloader: false,
            fixedContentPos: false,
        });
    }
    
    // GSAP animations
    if(typeof gsap !== 'undefined') {
        gsap.config({
            nullTargetWarn: false,
        });
    }
});
